import{_ as t,c as s,o as a,ag as r}from"./chunks/framework.CoPVQkzc.js";const p=JSON.parse('{"title":"User Management","description":"Users, roles, and authentication","frontmatter":{"title":"User Management","description":"Users, roles, and authentication"},"headers":[],"relativePath":"engine/user_management.md","filePath":"engine/user_management.md","lastUpdated":1788476353000}'),i={name:"engine/user_management.md"};function n(o,e,d,l,c,h){return a(),s("div",null,e[0]||(e[0]=[r(`<h1 id="user-management" tabindex="-1">User Management <a class="header-anchor" href="#user-management" aria-label="Permalink to &quot;User Management&quot;">​</a></h1><p>OIE maintains its own user accounts for anyone who needs to log in, whether through either administrator, the Command Line Interface, or the REST API. The Users view lets you create, edit, and remove these accounts. Role-based access control is available as a <a href="./extension_catalog.html#role-based-access-control">community extension</a> for restricting specific operations to designated user roles.</p><p>A password, including the admin account&#39;s, is reset from the <a href="./command_line_interface.html">Command Line Interface</a> with <code>user changepw</code>.</p><h2 id="default-account" tabindex="-1">Default account <a class="header-anchor" href="#default-account" aria-label="Permalink to &quot;Default account&quot;">​</a></h2><p>Every new OIE installation ships with a single administrator account:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Username</strong></td><td><code>admin</code></td></tr><tr><td><strong>Password</strong></td><td><code>admin</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Change the default password immediately on your first login. OIE displays a welcome dialog on first login that gives you the option to change it.</p></div><h2 id="users-view" tabindex="-1">Users view <a class="header-anchor" href="#users-view" aria-label="Permalink to &quot;Users view&quot;">​</a></h2><p>Open the Users view by clicking <strong>Users</strong> in the main navigation panel. The table displays all user accounts on the server.</p><h3 id="users-table-columns" tabindex="-1">Users table columns <a class="header-anchor" href="#users-table-columns" aria-label="Permalink to &quot;Users table columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Username</strong></td><td>The login name (must be unique)</td></tr><tr><td><strong>First Name</strong></td><td>The user&#39;s given name</td></tr><tr><td><strong>Last Name</strong></td><td>The user&#39;s family name</td></tr><tr><td><strong>Email</strong></td><td>The user&#39;s email address. This is the address used when an alert sends notifications to this user.</td></tr><tr><td><strong>Country</strong></td><td>Country of residence</td></tr><tr><td><strong>State/Territory</strong></td><td>State or territory (for users in the United States)</td></tr><tr><td><strong>Phone Number</strong></td><td>Contact phone number</td></tr><tr><td><strong>Organization</strong></td><td>The user&#39;s organization or company</td></tr><tr><td><strong>Role</strong></td><td>Their role within the organization (e.g. Employee - Engineer, Independent Contractor)</td></tr><tr><td><strong>Business</strong></td><td>The industry or field they work in (e.g. HIE, Hospital, Lab)</td></tr><tr><td><strong>Last Login</strong></td><td>Date and time of the most recent successful login</td></tr><tr><td><strong>Description</strong></td><td>An optional free-text description or notes field</td></tr></tbody></table><h2 id="managing-user-accounts" tabindex="-1">Managing user accounts <a class="header-anchor" href="#managing-user-accounts" aria-label="Permalink to &quot;Managing user accounts&quot;">​</a></h2><h3 id="creating-a-new-user" tabindex="-1">Creating a new user <a class="header-anchor" href="#creating-a-new-user" aria-label="Permalink to &quot;Creating a new user&quot;">​</a></h3><ol><li>Click <strong>New User</strong> in the task panel</li><li>Fill in the required fields (marked with a red asterisk): <ul><li><strong>Username</strong></li><li><strong>New Password</strong></li><li><strong>Confirm New Password</strong></li></ul></li><li>Optionally fill in the remaining profile fields: First Name, Last Name, Email, Country, State/Territory, Phone, Organization, Role, Business, Description</li><li>Click <strong>Finish</strong></li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Both password fields must match exactly. The username must not already exist in the system.</p></div><h3 id="editing-a-user" tabindex="-1">Editing a user <a class="header-anchor" href="#editing-a-user" aria-label="Permalink to &quot;Editing a user&quot;">​</a></h3><ol><li>Select the user in the table</li><li>Click <strong>Edit User</strong> in the task panel (or double-click the user row)</li><li>Modify any fields as needed. The Username field is editable, but the new name must be unique</li><li>Click <strong>Finish</strong></li></ol><h3 id="deleting-a-user" tabindex="-1">Deleting a user <a class="header-anchor" href="#deleting-a-user" aria-label="Permalink to &quot;Deleting a user&quot;">​</a></h3><ol><li>Select the user in the table</li><li>Click <strong>Delete User</strong> in the task panel</li><li>Confirm the deletion when prompted</li></ol><h3 id="user-tasks-summary" tabindex="-1">User tasks summary <a class="header-anchor" href="#user-tasks-summary" aria-label="Permalink to &quot;User tasks summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td>Reload the users table</td></tr><tr><td><strong>New User</strong></td><td>Open the new user dialog</td></tr><tr><td><strong>Edit User</strong></td><td>Open the selected user for editing</td></tr><tr><td><strong>Delete User</strong></td><td>Remove the selected user from the server</td></tr></tbody></table><h2 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h2><p>Password requirements are controlled through properties in <code>conf/mirth.properties</code>. By default all constraints are disabled (set to <code>0</code>), meaning any password is accepted.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>password.minlength</code></td><td>Minimum number of characters</td><td><code>0</code></td></tr><tr><td><code>password.minupper</code></td><td>Minimum uppercase letters</td><td><code>0</code></td></tr><tr><td><code>password.minlower</code></td><td>Minimum lowercase letters</td><td><code>0</code></td></tr><tr><td><code>password.minnumeric</code></td><td>Minimum digit characters</td><td><code>0</code></td></tr><tr><td><code>password.minspecial</code></td><td>Minimum special characters</td><td><code>0</code></td></tr><tr><td><code>password.retrylimit</code></td><td>Failed login attempts before the account is locked</td><td><code>0</code> (no limit)</td></tr><tr><td><code>password.lockoutperiod</code></td><td>Hours to keep the account locked (0 = locked until an admin unlocks it)</td><td><code>0</code></td></tr><tr><td><code>password.expiration</code></td><td>Days until the password expires (0 = never)</td><td><code>0</code></td></tr><tr><td><code>password.graceperiod</code></td><td>Days of grace after expiration during which the user can still log in</td><td><code>0</code></td></tr><tr><td><code>password.reuseperiod</code></td><td>Days that must pass before a previous password can be reused</td><td><code>0</code></td></tr><tr><td><code>password.reuselimit</code></td><td>Number of recent passwords that cannot be reused</td><td><code>0</code></td></tr></tbody></table><h3 id="recommended-production-settings" tabindex="-1">Recommended production settings <a class="header-anchor" href="#recommended-production-settings" aria-label="Permalink to &quot;Recommended production settings&quot;">​</a></h3><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minlength</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 8</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minupper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minlower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minnumeric</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.minspecial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.retrylimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.lockoutperiod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.expiration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 90</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password.reuselimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 5</span></span></code></pre></div><h2 id="first-login" tabindex="-1">First login <a class="header-anchor" href="#first-login" aria-label="Permalink to &quot;First login&quot;">​</a></h2><p>When you log in for the first time after a fresh installation, OIE presents a welcome dialog that lets you:</p><ol><li>Customize your user account information (first name, last name, email, etc.)</li><li>Optionally change the default admin password</li></ol><h2 id="username-behavior" tabindex="-1">Username behavior <a class="header-anchor" href="#username-behavior" aria-label="Permalink to &quot;Username behavior&quot;">​</a></h2><p>Usernames are case-insensitive by default: <code>Admin</code>, <code>admin</code>, and <code>ADMIN</code> all refer to the same account. A username can be changed after creation through the Edit User dialog, but the new name must be unique.</p>`,31)]))}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
